const D = { energy: .6, density: .55, scale: 1, speed: 1, artifact: .45, grid: .55, hue: 24, x: .5, y: .5, style: 'chart', act: 'sleep', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const md = (a, n) => ((a % n) + n) % n;
// integer hash — finalize with >>> (>> sign-extends and caps the hash at 0.5)
function h2(ix, iy) { let h = (ix * 374761393 + iy * 668265263 + (P.seed | 0) * 1442695041) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967295; }
function vn1(x, r) { const ix = Math.floor(x), fx = x - ix, ux = fx*fx*(3-2*fx); const a = h2(ix, r), b = h2(ix+1, r); return a + (b-a)*ux; }

const en = clp(P.energy, 0, 1), dens = clp(P.density, 0, 1), art = clp(P.artifact, 0, 1);
const W = width, H = height, u = Math.min(W, H);
const hs = P.hue - 24;

const ST = {
  // paper is TONED, not white: a near-white ground lands the frame ~0.59 and reads as
  // blank paper (the copperplate failure). [38,28,50] puts the frame at ~0.39.
  chart:   { pap:[38,28,50], ink:[26,30,10], grd:[8,62,44],  lbl:[26,26,16], gut:[36,20,38], glow:0 },
  monitor: { pap:[222,42,9], ink:[150,70,92],grd:[210,40,30], lbl:[190,18,78], gut:[222,38,14], glow:1 },
  blueprint:{pap:[212,60,28],ink:[200,7,97], grd:[200,32,52], lbl:[200,16,84], gut:[214,50,20], glow:0 },
  raster:  { pap:[240,30,8], ink:[20,90,96], grd:[240,24,22], lbl:[200,12,74], gut:[240,26,12], glow:1 }
};
const st = ST[P.style] || ST.chart;
const PAH = md(st.pap[0] + hs, 360), INH = md(st.ink[0] + hs, 360), GRH = md(st.grd[0] + hs, 360), LBH = md(st.lbl[0] + hs, 360), GUH = md(st.gut[0] + hs, 360);

const CH = ['Fp1-F3','F3-C3','C3-P3','P3-O1','Fp2-F4','F4-C4','C4-P4','P4-O2','Fp1-F7','F7-T3','T3-T5','T5-O1','Fp2-F8','F8-T4','T4-T6','T6-O2','EOG-L','EOG-R','EMG','ECG'];
const NCH = clp(6 + Math.round(dens * 14), 6, 20);

// ---- sleep staging: the multi-minute dramaturgy, indexed off K.section ----
const STAGES = ['W','N1','N2','N2','N3','N3','REM','N1'];
let stage = STAGES[md(K.section, 8)];
if (P.act === 'awake') stage = md(K.section, 8) < 4 ? 'W' : 'N1';
else if (P.act === 'seizure') stage = md(K.section, 8) === 3 || md(K.section, 8) === 6 ? 'SZ' : 'W';
const stIdx = { W:0, N1:1, N2:2, N3:3, REM:4, SZ:5 }[stage];

// per-stage character: [alphaAmp, thetaAmp, deltaAmp, betaAmp, spindleRate, kRate, emg, eog]
const CHAR = {
  W:   [.85,.18,.06,.42, 0,   0,   .9, .5],
  N1:  [.32,.62,.16,.20, 0,   .06, .5, .3],
  N2:  [.10,.48,.42,.14, .55, .30, .3, .05],
  N3:  [.05,.30,1.15,.08,.10, .10, .2, .02],
  REM: [.20,.55,.10,.30, 0,   0,   .06,1.6],
  SZ:  [.10,.35,.55,.95, 0,   0,   .8, .4]
};
const ch = CHAR[stage] || CHAR.W;

// ---- the signal: pure function of channel + absolute time ----
function sig(c, t) {
  const post = (c === 3 || c === 11 || c === 15 || c === 2 || c === 6);   // posterior: alpha lives here
  const front = c < 2 || c === 4 || c === 8 || c === 12;
  let v = 0;
  v += 0.55 * (vn1(t * 46 + c * 91.3, 11) - .5);                                  // broadband EEG noise
  v += ch[1] * 0.85 * Math.sin(t * 6.2 * 6.28 + c * 1.7) * (0.6 + 0.6 * vn1(t * 2.3 + c * 7, 3));  // theta
  v += ch[2] * 1.35 * Math.sin(t * 1.15 * 6.28 + c * .9 + 2.1 * vn1(t * .6, 5));  // delta
  if (post) v += ch[0] * 1.05 * Math.sin(t * 10.1 * 6.28 + c * 2.3) * clp(vn1(t * 1.1 + c, 7) * 2.4 - .5, 0, 1);  // posterior alpha, waxing/waning
  v += ch[3] * 0.30 * Math.sin(t * 21 * 6.28 + c * 3.1);                          // beta
  // sleep spindles: 12-14 Hz bursts, central channels
  if (ch[4] > 0) {
    const per = 2.2 / Math.max(ch[4], .01), i = Math.floor(t / per);
    const t0 = i * per + h2(i, 21) * per * .7, dt = t - t0;
    if (dt > 0 && dt < .85 && (c === 1 || c === 2 || c === 5 || c === 6)) v += 0.95 * Math.sin(dt * 13.2 * 6.28) * Math.sin(Math.PI * dt / .85);
  }
  // K-complexes: a big biphasic slow wave
  if (ch[5] > 0) {
    const per = 3.4 / Math.max(ch[5], .01), i = Math.floor(t / per);
    const t0 = i * per + h2(i, 33) * per * .8, dt = t - t0;
    if (dt > 0 && dt < 1.1) { const e = Math.sin(Math.PI * dt / 1.1); v += 2.3 * e * (-Math.sin(dt * 1.35 * 6.28)); }
  }
  if (stage === 'SZ') {                                                            // spike-and-wave 3 Hz
    const ph = md(t * 3.0, 1);
    v += 2.1 * (Math.exp(-ph * 26) * 1.6 - 0.55 * Math.sin(ph * 6.28));
  }
  if (c === 16 || c === 17) {                                                      // EOG: eye movements
    v = 0.25 * (vn1(t * 20 + c * 5, 13) - .5);
    const rem = ch[7];
    v += rem * 1.7 * Math.tanh(6 * Math.sin(t * (stage === 'REM' ? 1.9 : .35) * 6.28 + c * 3.14)) * clp(vn1(t * .8 + c, 17) * 2.2 - .6, 0, 1) * (c === 17 ? -1 : 1);
  } else if (c === 18) {                                                           // EMG: chin tone
    v = ch[6] * 1.5 * (vn1(t * 160, 19) - .5) * (0.7 + 0.9 * vn1(t * 1.7, 23));
  } else if (c === 19) {                                                           // ECG: QRS
    const ph = md(t * (1.05 + .16 * Math.sin(t * .13)), 1);
    v = 2.6 * Math.exp(-Math.pow((ph - .12) / .014, 2)) - 0.5 * Math.exp(-Math.pow((ph - .09) / .03, 2)) + 0.42 * Math.exp(-Math.pow((ph - .30) / .05, 2));
    v -= 0.35;
  } else {
    // artifacts: frontal eye-blinks + wandering electrode pop
    if (front && art > 0) {
      const per = 3.1, i = Math.floor(t / per), t0 = i * per + h2(i, 41) * per * .8, dt = t - t0;
      if (dt > 0 && dt < .42) v += art * 3.4 * Math.sin(Math.PI * dt / .42);
    }
    if (art > 0 && h2(Math.floor(t * 1.4) + c * 7, 51) > 0.985) v += art * 2.2 * (vn1(t * 90, 53) - .5);
    v += art * 0.22 * Math.sin(t * 50 * 6.28 + c);                                 // mains hum
  }
  return v;
}

// ---- scrolling buffer: paper + grid + trace, written a column at a time ----
const BW = Math.max(64, Math.min(Math.round(W), 1600)), BH = Math.max(64, Math.min(Math.round(H), 1000));
const PXPS = 34 * clp(P.scale, .3, 2.2);              // paper mm/s -> px/s
const GUT = 0.11;                                     // left gutter (labels) as a frame fraction
const bkey = BW + 'x' + BH + '|' + P.style + '|' + Math.round(P.hue) + '|' + NCH + '|' + (P.seed | 0);
if (!S.buf || S.bkey !== bkey) { if (S.buf && S.buf.remove) S.buf.remove(); S.buf = createGraphics(BW, BH); S.buf.pixelDensity(1); S.buf.colorMode(S.buf.HSB, 360, 100, 100, 100); S.bkey = bkey; S.fill = true; }
const buf = S.buf;
const chH = BH / NCH;
const chY = c => (c + .5) * chH;

function column(x, t, prev) {
  buf.noStroke();
  buf.fill(PAH, st.pap[1], st.pap[2]);
  buf.rect(x, 0, 1.3, BH);
  // chart grid printed on the paper, scrolling with it: 1 s major, 0.2 s minor
  const gA = clp(P.grid, 0, 1);
  const maj = Math.floor(t / 1) !== Math.floor((t - 1 / PXPS) / 1);
  const min5 = Math.floor(t / .2) !== Math.floor((t - 1 / PXPS) / .2);
  if (maj) { buf.fill(GRH, st.grd[1], st.grd[2], 62 * gA); buf.rect(x, 0, 1.2, BH); }
  else if (min5) { buf.fill(GRH, st.grd[1], st.grd[2], 26 * gA); buf.rect(x, 0, 1, BH); }
  buf.fill(GRH, st.grd[1], st.grd[2], 34 * gA);
  for (let c = 0; c < NCH; c++) buf.rect(x, chY(c), 1.2, 1);
  const amp = chH * .40 * (0.42 + en * 1.5);
  if (P.style === 'raster') {                    // radically abstracted: amplitude density band
    for (let c = 0; c < NCH; c++) {
      let mx = 0;
      for (let k = 0; k < 4; k++) mx = Math.max(mx, Math.abs(sig(c, t + k * 0.004)));
      const a = clp(mx / 3.2, 0, 1);
      buf.fill(md(INH + 150 - 150 * a, 360), st.ink[1] * (.4 + .6 * a), st.ink[2] * (.25 + .75 * a), 92);
      buf.rect(x, c * chH + 1, 1.3, chH - 2);
    }
    return;
  }
  buf.stroke(INH, st.ink[1], st.ink[2], 94); buf.strokeWeight(1.15);
  for (let c = 0; c < NCH; c++) {
    const y0 = chY(c) - clp(prev[c], -3.6, 3.6) * amp;
    const v = sig(c, t);
    const y1 = chY(c) - clp(v, -3.6, 3.6) * amp;
    buf.line(x - 1.3, y0, x, y1);
    prev[c] = v;
  }
}

let want = Math.floor(K.t * PXPS);
if (S.col == null || want < S.col || want - S.col > BW) { S.col = want - 1; S.fill = true; }
if (!S.prev || S.prev.length !== NCH) { S.prev = new Float32Array(NCH); S.fill = true; }
if (S.fill) {
  for (let i = 0; i < BW; i++) { const t = (want - (BW - 1 - i)) / PXPS; column(i, t, S.prev); }
  S.head = md(want, BW); S.col = want; S.fill = false;
} else {
  let n = clp(want - S.col, 0, 40);
  for (let i = 0; i < n; i++) { const c0 = md(S.col + 1 + i, BW), t = (S.col + 1 + i) / PXPS; column(c0, t, S.prev); }
  if (n > 0) { S.col = want; S.head = md(want, BW); }
}

// =================== composite ===================
noStroke();
background(PAH, st.pap[1], st.pap[2] * .5);
// newest column sits at the right edge: blit the ring buffer in two pieces
const gx = GUT * W, gw = W - gx;
const hd = (S.head + 1) % BW;
const w1 = BW - hd;
push();
translate(0, (P.y - .5) * H * .12);
image(buf, gx, 0, gw * (w1 / BW), H, hd, 0, w1, BH);
image(buf, gx + gw * (w1 / BW), 0, gw * (hd / BW), H, 0, 0, hd, BH);
pop();

if (st.glow) {   // monitor styles get a soft bloom on FEW shapes (shadowBlur reset below)
  const dcx = drawingContext;
  blendMode(ADD); noStroke(); fill(INH, st.ink[1] * .6, st.ink[2], 4.5 * en);
  rect(gx, 0, gw, H);
  blendMode(BLEND); dcx.shadowBlur = 0;
}

// left gutter: channel montage labels + a calibration pulse
fill(GUH, st.gut[1], st.gut[2]); rect(0, 0, gx, H);
textFont('Courier New');
const ts = clp(Math.min(u * .0125, chH * (H / BH) * .5), 6, 20);
textSize(ts); textAlign(RIGHT, CENTER);
for (let c = 0; c < NCH; c++) {
  const yy = chY(c) * (H / BH) + (P.y - .5) * H * .12;
  noStroke(); fill(LBH, st.lbl[1], st.lbl[2], 90);
  text(CH[c], gx - u * .028, yy);
  stroke(LBH, st.lbl[1], st.lbl[2], 46); strokeWeight(1);        // 50 µV calibration square
  const ch2 = (H / NCH) * .18 * (0.42 + en * 1.5);
  noFill(); beginShape();
  vertex(gx - u * .020, yy + ch2); vertex(gx - u * .014, yy + ch2);
  vertex(gx - u * .014, yy - ch2); vertex(gx - u * .006, yy - ch2); vertex(gx - u * .006, yy + ch2);
  endShape();
}
noStroke(); fill(LBH, st.lbl[1], st.lbl[2], 92);
textAlign(LEFT, TOP); textSize(clp(u * .014, 7, 26));
text('POLYSOMNOGRAM', u * .016, u * .022);
textSize(clp(u * .0105, 6, 19)); fill(LBH, st.lbl[1], st.lbl[2] * .8, 66);
text('10-20  ·  30 mm/s', u * .016, u * .044);
text('50 µV', u * .016, u * .062);

// stage banner + epoch clock — the arc made legible
const el = K.t + 0;
const ep = Math.floor(el / 30);
textAlign(RIGHT, TOP); textSize(clp(u * .0125, 6, 22));
fill(LBH, st.lbl[1], st.lbl[2] * .8, 70);
text('EPOCH ' + String(ep % 10000).padStart(4, '0') + '   ' + String(Math.floor(md(el / 60, 60))).padStart(2, '0') + ':' + String(Math.floor(md(el, 60))).padStart(2, '0'), W - u * .024, u * .022);
const SC = { W:[45,80,88], N1:[190,55,74], N2:[210,62,80], N3:[250,58,72], REM:[330,70,86], SZ:[8,88,92] }[stage] || [45,80,88];
noStroke(); fill(md(SC[0] + hs, 360), SC[1], SC[2], 26 + 16 * K.swell);
rect(W - u * .115, u * .046, u * .091, u * .030, 2);
fill(md(SC[0] + hs, 360), SC[1] * .5, 100, 96);
textAlign(CENTER, CENTER); textSize(clp(u * .015, 7, 27));
text('STAGE ' + stage, W - u * .115 + u * .0455, u * .046 + u * .015);

// the pen bar: a bright edge where the trace is being laid down
stroke(md(SC[0] + hs, 360), SC[1] * .6, 96, 62); strokeWeight(1.6);
line(W - 1.5, 0, W - 1.5, H);

// paper vignette (broad, soft)
blendMode(MULTIPLY);
noFill(); stroke(0, 0, 46, 26); strokeWeight(u * .085);
rect(-u * .043, -u * .043, W + u * .086, H + u * .086);
blendMode(BLEND);
drawingContext.shadowBlur = 0;
if (P.alpha < 100) { noStroke(); fill(PAH, st.pap[1], st.pap[2] * .5, 100 - clp(P.alpha, 0, 100)); rect(0, 0, W, H); }
